<script setup lang="ts">
import { computed, ref } from "vue";
import { http } from "@/utils/http";
type Job = Record<string, any>; const rows = ref<Job[]>([]); const loading = ref(false); const error = ref(""); const status = ref(""); const query = ref(""); const detail = ref<Job | null>(null); const counts = computed(() => ({ running: rows.value.filter(row => String(row.status).toUpperCase() === 'RUNNING').length, queued: rows.value.filter(row => String(row.status).toUpperCase() === 'QUEUED').length, failed: rows.value.filter(row => String(row.status).toUpperCase() === 'FAILED').length }));
async function load() { loading.value = true; try { const result: any = await http.get("/background-tasks"); const values = Array.isArray(result) ? result : (result?.content || result?.items || []); rows.value = values.filter((row: Job) => !status.value || String(row.status).toUpperCase() === status.value); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "运维任务加载失败"; } finally { loading.value = false; } }
const filtered = computed(() => query.value ? rows.value.filter(row => JSON.stringify(row).toLowerCase().includes(query.value.toLowerCase())) : rows.value); load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">定时任务与运维作业</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">查看作业状态、进度和最近运行结果。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><div class="grid grid-cols-1 md:grid-cols-4 gap-4 mb-5"><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">运行中</div><div class="text-2xl font-semibold mt-2">{{ counts.running }}</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">排队中</div><div class="text-2xl font-semibold mt-2">{{ counts.queued }}</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">最近失败</div><div class="text-2xl font-semibold mt-2">{{ counts.failed }}</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">最近完成</div><div class="text-2xl font-semibold mt-2">{{ rows.length - counts.running - counts.queued - counts.failed }}</div></el-card></div><div class="flex gap-3 mb-4"><el-input v-model="query" clearable placeholder="搜索 Job ID / 类型 / 子系统" class="max-w-md"/><el-select v-model="status" clearable placeholder="状态" @change="load"><el-option label="运行中" value="RUNNING"/><el-option label="排队中" value="QUEUED"/><el-option label="失败" value="FAILED"/><el-option label="完成" value="COMPLETED"/></el-select></div><el-skeleton v-if="loading" :rows="8" animated/><el-card v-else shadow="never"><el-empty v-if="!filtered.length" description="暂无运维作业"/><el-table v-else :data="filtered" stripe><el-table-column prop="id" label="Job ID" min-width="240"/><el-table-column prop="type" label="类型" width="160"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="progress" label="进度" width="150"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link @click="detail = row">详情</el-button></template></el-table-column></el-table></el-card><el-drawer v-model="detail" title="作业详情" size="480px"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="Job ID">{{ detail.id }}</el-descriptions-item><el-descriptions-item label="类型">{{ detail.type || '—' }}</el-descriptions-item><el-descriptions-item label="状态">{{ detail.status || '—' }}</el-descriptions-item><el-descriptions-item label="失败分类">{{ detail.errorCategory || '—' }}</el-descriptions-item><el-descriptions-item label="可重试">{{ detail.retryable === true ? '是' : '由后端策略决定' }}</el-descriptions-item></el-descriptions></el-drawer></main></template>
